    ,t.b_id = #{newBId}


    , t.machine_id= #{machineId}


    , t.spec_cd= #{specCd}


    , t.community_id= #{communityId}


    , t.value= #{value}

where 1=1

    and t.param_id= #{paramId}


    and t.machine_id= #{machineId}


    and t.community_id= #{communityId}

